  "· Sonra:": "· После:",
  "🏟️ Satıştaki takımları gör ve satın al. Listings kullanıcı ve botların ilanlarından oluşur.": "🏟️ Просматривай и покупай команды, выставленные на продажу. Объявления размещают как пользователи, так и боты.",
  "🏟️ Takımlar": "🏟️ Команды",
  "💡 Diamond ile oyuncu transfer eder, tesis yükseltir, item ve takım satın alabilirsin. Büyük paketler kademeli bonus kazandırır.": "💡 За алмазы можно подписывать игроков, улучшать инфраструктуру и покупать предметы или команды. Крупные пакеты дают всё больший бонус.",
  "2 sezon": "2 сезона",
  "Aynısını tekrar yaz": "Введи то же самое ещё раз",
  "Beceri puanı maç motoruna ±%5 etki eder. Uzmanlık alanı belirli istatistiklere bonus verir.": "Очки навыков влияют на матчевый движок на ±5%. Специализация даёт бонус к определённым характеристикам.",
  "Bonservis ve maaş sistemce belirlenmiştir. Maaş sezonun 10., 20., 30. ve 40. günlerinde 4 taksit halinde takım kasasından oyuncu cüzdanına ödenir.": "Трансферная сумма и зарплата устанавливаются системой. Зарплата выплачивается из казны команды в кошелёк игрока 4 частями — в 10-й, 20-й, 30-й и 40-й дни сезона.",
  "Bu oyuncu zaten kadronda": "Этот игрок уже в твоём составе",
  "Daha Sonra": "Позже",
  "Hesabın için yeni bir şifre yaz.": "Придумай новый пароль для аккаунта.",
  "Hesabını silmek kalıcıdır. Takımın, oyuncun, cüzdanın ve tüm ilerlemen geri alınamaz şekilde kaldırılır.": "Удаление аккаунта необратимо. Твоя команда, игрок, кошелёк и весь прогресс будут удалены безвозвратно.",
  "Kupondan çıkar": "Убрать из купона",
  "Opsiyonel. Onay verildiği an oyuncunun elmas cüzdanına aktarılır. Kasa elması (€ değil) kullanılır.": "Необязательно. Переводится в алмазный кошелёк игрока в момент одобрения. Используются алмазы казны (не €).",
  "Oyuncu Transfer › Boştaki Oyuncular kısmına eklenecek. Yerine yeni bir oyuncu gelecek.": "Игрок будет добавлен в Трансферы › Свободные агенты. Его место займёт новый игрок.",
  "Oyuncu seviyesine göre hesaplandı (40 günlük antrenman maliyeti × 1,045).": "Рассчитано по уровню игрока (стоимость 40 дней тренировок × 1,045).",
  "Oyuncunun mevcut piyasa değeri. Onay verildiği an satıcı kasasına aktarılır.": "Текущая рыночная стоимость игрока. Переводится в казну продавца в момент одобрения.",
  "PUAN": "ОЧКИ",
