  "seçebilirsin. Kaptan onaylarsa sözleşme imzalanır; maaş sezonun 10/20/30/40. günlerinde 4 taksit halinde ödenir.": "можешь выбрать. Если капитан одобрит, контракт будет подписан; зарплата выплачивается 4 частями в 10/20/30/40-й дни сезона.",
