  "8 grubun 1. ve 2.'leri Son 16'ya yükselir (16 takım). Final hariç tüm turlar çift maçlıdır (ev+deplasman, toplam skor).": "Команды, занявшие 1-е и 2-е места в 8 группах, выходят в 1/8 финала (16 команд). Все раунды, кроме финала, состоят из двух матчей (дома и в гостях, по сумме двух матчей).",
  "8 grubun ilk 2'si Son 16'ya yükselir. Her tur tek maç eleme (berabere durumunda penaltı).": "Первые 2 команды из 8 групп выходят в 1/8 финала. Каждый раунд — один матч на выбывание (при ничьей — серия пенальти).",
  "CON grupların 1-2'leri (16) + ELI gruplarının 3-4'leri (16) = 32 takım Son 32'de buluşur. Final hariç tüm turlar çift maçlıdır.": "1–2-е места групп CON (16) + 3–4-е места групп ELI (16) = 32 команды встречаются в 1/16 финала. Все раунды, кроме финала, состоят из двух матчей.",
  "ELI grupların 1-2'leri (16) + CHM gruplarının 3-4'leri (16) = 32 takım Son 32'de buluşur. Final hariç tüm turlar çift maçlıdır.": "1–2-е места групп ELI (16) + 3–4-е места групп CHM (16) = 32 команды встречаются в 1/16 финала. Все раунды, кроме финала, состоят из двух матчей.",
  "Her ülkenin Süper Lig 1. ve 2. sırası (32×2=64 takım)": "1-е и 2-е места Суперлиги каждой страны (32×2=64 команды)",
  "Her ülkenin Süper Lig 1. ve 2. sırası (32×2=64 → Play-Off → 32 takım)": "1-е и 2-е места Суперлиги каждой страны (32×2=64 → Плей-офф → 32 команды)",
  "Her ülkenin Süper Lig 3. ve 4. sırası (32×2=64 takım)": "3-е и 4-е места Суперлиги каждой страны (32×2=64 команды)",
  "Her ülkenin Süper Lig 3. ve 4. sırası (32×2=64 → PO1 → PO2 → 32 takım)": "3-е и 4-е места Суперлиги каждой страны (32×2=64 → PO1 → PO2 → 32 команды)",
  "Her ülkenin Süper Lig 5. ve 6. sırası (32×2=64 takım)": "5-е и 6-е места Суперлиги каждой страны (32×2=64 команды)",
  "Her ülkenin Süper Lig 5. ve 6. sırası (32×2=64 → PO1 → PO2 → 32 takım)": "5-е и 6-е места Суперлиги каждой страны (32×2=64 → PO1 → PO2 → 32 команды)",
  "Eleme turu fikstürü, grup aşaması tamamlandığında otomatik oluşturulacak.": "Сетка плей-офф будет сформирована автоматически после завершения группового этапа.",
  "Gruplarını tamamlayan takımlar elemeye yükseldi. Rakipler, üst lig grupları bittikçe eşleştirilecek.": "Команды, завершившие групповой этап, вышли в плей-офф. Соперники будут определены по мере завершения групп лиг высшего уровня.",
  "EURO Cup sezon içinde kurulur.": "EURO Cup формируется по ходу сезона.",
