  "Bu günlerde lig maçları oynanmaz. Takımlar transfer pazarı açık kalır;": "В эти дни матчи лиги не проводятся. Трансферный рынок для команд остаётся открытым;",
  "Bugün için hiçbir lige veya turnuvaya kupon yatırılmamış. İlk kuponu sen yatırırsan havuzu sen başlatırsın.": "Сегодня ещё никто не сделал купон ни на одну лигу или турнир. Сделай первый купон — и ты откроешь пул.",
  "Ev sahibi maçlarda bilet geliri sağlayan taraftar kapasitesi. Süper Lig'de €25/bilet, alt liglerde daha az.": "Вместимость трибун, приносящая доход от билетов в домашних матчах. В Суперлиге — €25/билет, в низших лигах — меньше.",
  "Bilet satışı gelirlerini yüzdelik olarak artırır.": "Увеличивает доход от продажи билетов на определённый процент.",
  "Günlük 450 enerjiye ek, takımdaki tüm oyunculara bonus enerji sağlar.": "Сверх ежедневных 450 единиц энергии даёт бонусную энергию всем игрокам команды.",
  "Aynı anda kaç oyuncunun yetenek çalışabileceğini belirler.": "Определяет, сколько игроков могут одновременно тренировать навыки.",
  "Bu davet zorunludur — milli takım maçlarında oynamakla yükümlüsünüz.": "Этот вызов обязателен — нужно играть в матчах сборной.",
  "Adaylıktan çekilmek istediğinden emin misin? Çekildikten sonra tekrar aday olabilirsin (oylama başlamadan önce).": "Точно снять кандидатуру? После этого можно снова выдвинуться (до начала голосования).",
  "Bu botu takımdan çıkarmak istediğine emin misin?": "Точно убрать этого бота из команды?",
