  "⏰ UZATMA BAŞLIYOR! 90 dakika yetmedi, 30 dakika daha oynanacak.": "⏰ ДОПОЛНИТЕЛЬНОЕ ВРЕМЯ! 90 минут не хватило — впереди ещё 30.",
  "🔃 Uzatmanın 1. devresi bitti, takımlar saha değiştiriyor.": "🔃 Первый тайм дополнительного времени окончен, команды меняются воротами.",
  "🎯 Maç penaltı atışlarına gitti! Şimdi kalbi olan kazanır.": "🎯 Дело дошло до серии пенальти! Теперь всё решат нервы.",
