  "⚖️ Dengeli: Normal hücum/savunma dağılımı.": "⚖️ Баланс: обычное соотношение атаки и защиты.",
  "🗡️ Hücum: Daha fazla gol şansı, savunma açık. Kart riski +.": "🗡️ Атака: больше голевых моментов, но защита открыта. Риск карточек +.",
  "🔥 Aşırı Hücum: Maksimum saldırı, çok riskli. Kart + sakatlık ihtimali +++.": "🔥 Тотальная атака: максимум нападения, очень рискованно. Риск карточек и травм +++.",
  "🛡️ Defansif: Az gol yeme, düşük kart riski. Atak çok sınırlı.": "🛡️ Оборона: меньше пропущенных, низкий риск карточек. Атака сильно ограничена.",
  "💡 Strateji değişiklikleri direkt motora etki eder": "💡 Смена стратегии напрямую влияет на движок матча",
