  "🏆 İnanılmaz! Top oyunculardan birisin.": "🏆 Невероятно! Ты один из лучших игроков.",
  "👑 Efsane oluyorsun! Sahanın hakimi sensin.": "👑 Ты становишься легендой! Поле принадлежит тебе.",
  "💎 SEN BİR EFSANESİN! Tüm dünya seni izliyor.": "💎 ТЫ ЛЕГЕНДА! Весь мир следит за тобой.",
